    /// Replace an item's details
    ///
    /// Full replacement of the user-editable `details`: a property left out is cleared.
    /// `expectedVersion` must equal the item's current `version`, otherwise the server
    /// answers `409 version_conflict` and the client refetches. Changing details never
    /// changes a live marketplace listing; use the listing actions for that.
    ///
    ///
    /// - Remark: HTTP `PUT /v1/items/{itemId}`.
    /// - Remark: Generated from `#/paths//v1/items/{itemId}/put(replaceItem)`.
    public func replaceItem(
        path: Operations.ReplaceItem.Input.Path,
        headers: Operations.ReplaceItem.Input.Headers = .init(),
        body: Operations.ReplaceItem.Input.Body
    ) async throws -> Operations.ReplaceItem.Output {
        try await replaceItem(Operations.ReplaceItem.Input(
            path: path,
            headers: headers,
            body: body
        ))
